   text: {  
    bn: "শব্দের মাধ্যমে কুইজমের ধারণা, প্রতীক ও দর্শনের ব্যাখ্যা...",
    en: "The living vocabulary through which Quism explains its concepts, symbols, and philosophy...",
    hi: "वह जीवित शब्द-संसार जिसके माध्यम से क्विज़्म अपने विचारों, प्रतीकों और दर्शन की व्याख्या करता है...", 
    sa: "शब्दानां माध्यमेन क्विस्म-दर्शनस्य तत्त्वानि, प्रतीकानि च विवृणोति...",
 },  
